from __future__ import annotations

from decimal import Decimal
from typing import Any


def _value(record: dict[str, Any] | None, key: str) -> Any:
    if not record:
        return ""
    return record.get(key, "")


def _numeric(value: Any) -> Decimal:
    if value is None or value == "":
        return Decimal("0")
    return Decimal(str(value))


def _lookup(
    tables: dict[str, list[dict[str, Any]]] | None,
    table: str,
    key_col: str,
    key_val: Any,
    out_col: str,
) -> Any:
    if not tables:
        return ""

    for row in tables.get(table, []):
        if row.get("DEL_FLG", "") == "Y":
            continue
        if row.get(key_col, "") == key_val:
            return row.get(out_col, "")
    return ""


def _failure(code: str, message: str) -> dict[str, str]:
    return {
        "code": code,
        "message": message,
        "severity": "BLOCK",
    }


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    tables: dict | None = None,
    table: str = "ORD_HEADER",
) -> list[dict]:
    errors: list[dict] = []

    if table == "ORD_HEADER":
        # ORD-001
        if event in {"INSERT", "UPDATE"}:
            discount = _numeric(_value(record, "DISC_PCT"))
            if not (discount >= Decimal("0") and discount <= Decimal("100")):
                errors.append(_failure("E5001", "Discount out of range"))

        # ORD-002
        if event == "UPDATE":
            discount = _numeric(_value(record, "DISC_PCT"))
            role = _lookup(
                tables,
                "USR_MASTER",
                "USR_ID",
                _value(record, "OWNER_UID"),
                "ROLE_ID",
            )
            if not (
                not (
                    discount > Decimal("20")
                    and role != "MGR"
                    and role != "ADMIN"
                )
            ):
                errors.append(
                    _failure(
                        "E5002",
                        "Discount over 20 percent requires manager role",
                    )
                )

        # ORD-003
        if event == "UPDATE":
            old_status = _value(old, "STAT_CD")
            status = _value(record, "STAT_CD")
            if not (
                not (
                    old_status == "I"
                    and status != "I"
                    and status != "X"
                )
            ):
                errors.append(
                    _failure(
                        "E5003",
                        "Invoiced order can only be cancelled",
                    )
                )

    elif table == "ORD_LINE":
        # ORD-004
        if event in {"INSERT", "UPDATE"}:
            quantity = _numeric(_value(record, "QTY"))
            if not quantity > Decimal("0"):
                errors.append(
                    _failure("E5004", "Quantity must be positive")
                )

        # ORD-005
        if event == "INSERT":
            active_flag = _lookup(
                tables,
                "PROD_MASTER",
                "PROD_ID",
                _value(record, "PROD_ID"),
                "ACTIVE_FLG",
            )
            if active_flag != "Y":
                errors.append(
                    _failure("E5005", "Product not active")
                )

    return errors


def is_blocked(errors: list[dict]) -> bool:
    return any(error.get("severity") == "BLOCK" for error in errors)
